 @Test void successfulOriginalGetFormalSnapshotAndB077Evidence()throws Exception{try(var x=new Fixture()){var r=x.prepare();assertEquals(SOURCE,r.path("data_policy_evidence").path("source_version").asText());assertEquals(PARSE,r.path("data_policy_evidence").path("parse_version").asText());assertTrue(x.f.requests.get()>0);assertEquals(1,x.f.snapshots.size());assertEquals(4,x.writes.size());assertTrue(x.f.registrations.isEmpty());assertEquals(r,x.service.read(x.f.subject,"1",r.path("preparation_id").asText()).path("receipt"));}}
 @Test void candidateIsActualAndSideEffectFree()throws Exception{try(var x=new Fixture()){var c=x.service.candidate(x.f.subject,"1",MODEL);assertEquals("NOT_READ",c.path("original_validation").asText());assertEquals(SOURCE,c.path("policy_basis").path("version_id").asText());assertTrue(x.writes.isEmpty());assertTrue(x.f.snapshots.isEmpty());assertEquals(0,x.f.requests.get());}}
 @Test void sameOriginalKeyReturnsOriginalReceiptAndRecoveryBody()throws Exception{try(var x=new Fixture()){var r=x.prepare();assertEquals(r,x.prepare());assertEquals(1,x.f.snapshots.size());assertEquals(4,x.writes.size());var recovered=x.service.recover(x.f.subject,"1",r.path("operation_id").asText());assertEquals(x.request(),recovered.path("original_request"));assertEquals(KEY,recovered.path("original_idempotency_key").asText());assertEquals("1",recovered.path("original_context_revision").asText());}}
 @Test void modelEnableMandatoryBeforeGet()throws Exception{try(var x=new Fixture()){x.f.grants.removeIf(g->g.action().equals("model.enable"));assertThrows(TenantAccessException.class,x::prepare);assertEquals(0,x.f.requests.get());assertTrue(x.writes.isEmpty());}}
